/* USER CODE BEGIN 4 */
void EXTI0_IRQHandler(void){
	static uint32_t last_press_time = 0;   // remembers last valid press time
	    uint32_t now = HAL_GetTick();          // current system time (ms since startup)

	    // --- Debounce check ---
	    // Only process if at least 200 ms have passed since the last valid press.
	    if ((now - last_press_time) > 200) {
	        last_press_time = now;   // update reference time when we accept a press

	        // --- Cycle waveform state ---
	        if (state != 5) {
	            state += 1;
	        } else {
	            state = 0;
	        }

	        // --- Switch statement for waveform selection ---
	        switch (state) {
	            case 0:
	                lcd_command(CLEAR);
	                lcd_putstring("Sine");
	                __HAL_TIM_DISABLE_DMA(&htim2, TIM_DMA_CC1);
	                  HAL_DMA_Abort_IT(htim2.hdma[TIM_DMA_ID_CC1]);
	                	                HAL_DMA_Start_IT(&hdma_tim2_ch1,
	                	                                 (uint32_t)Sine_LUT,
	                	                                 (uint32_t)&(TIM3->CCR3),
	                	                                 NS2);
	                	                __HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
	                break;

	            case 1:
	                lcd_command(CLEAR);
	                lcd_putstring("Sawtooth");

	                __HAL_TIM_DISABLE_DMA(&htim2, TIM_DMA_CC1);
	                HAL_DMA_Abort_IT(htim2.hdma[TIM_DMA_ID_CC1]);
	                HAL_DMA_Start_IT(&hdma_tim2_ch1,
	                                 (uint32_t)Saw_LUT,
	                                 (uint32_t)&(TIM3->CCR3),
	                                 NS2);
	                __HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
	                break;

	            case 2:
	                lcd_command(CLEAR);
	                lcd_putstring("Triangular");

	                __HAL_TIM_DISABLE_DMA(&htim2, TIM_DMA_CC1);
	                HAL_DMA_Abort_IT(htim2.hdma[TIM_DMA_ID_CC1]);
	                HAL_DMA_Start_IT(&hdma_tim2_ch1,
	                                 (uint32_t)Triangle_LUT,
	                                 (uint32_t)&(TIM3->CCR3),
	                                 NS2);
	                __HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
	                break;

	            case 3:
	                lcd_command(CLEAR);
	                lcd_putstring("Piano");

	                __HAL_TIM_DISABLE_DMA(&htim2, TIM_DMA_CC1);
	                HAL_DMA_Abort_IT(htim2.hdma[TIM_DMA_ID_CC1]);
	                HAL_DMA_Start_IT(&hdma_tim2_ch1,
	                                 (uint32_t)Piano_LUT,
	                                 (uint32_t)&(TIM3->CCR3),
	                                 NS2);
	                __HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
	                break;

	            case 4:
	                lcd_command(CLEAR);
	                lcd_putstring("Guitar");

	                __HAL_TIM_DISABLE_DMA(&htim2, TIM_DMA_CC1);
	                HAL_DMA_Abort_IT(htim2.hdma[TIM_DMA_ID_CC1]);
	                HAL_DMA_Start_IT(&hdma_tim2_ch1,
	                                 (uint32_t)Guitar_LUT,
	                                 (uint32_t)&(TIM3->CCR3),
	                                 NS2);
	                __HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
	                break;

	            case 5:
	                lcd_command(CLEAR);
	                lcd_putstring("Drum");

	                __HAL_TIM_DISABLE_DMA(&htim2, TIM_DMA_CC1);
	                HAL_DMA_Abort_IT(htim2.hdma[TIM_DMA_ID_CC1]);
	                HAL_DMA_Start_IT(&hdma_tim2_ch1,
	                                 (uint32_t)Drum_LUT,
	                                 (uint32_t)&(TIM3->CCR3),
	                                 NS2);
	                __HAL_TIM_ENABLE_DMA(&htim2, TIM_DMA_CC1);
	                break;

	            default:
	                break;
	        }
	    }

	    // --- Clear EXTI interrupt flag ---
	    HAL_GPIO_EXTI_IRQHandler(GPIO_PIN_0);
}
